// Runtime side of the x87 -> SSE2 translations generated by xlat.py.
#pragma once

#include <windows.h>
#include <cstdint>
#include <cstring>

struct MxoXFunc {
  uint32_t        rva;          // function start in the image
  uint32_t        size;         // length of the original code
  void*           replacement;  // translated code
  const uint8_t*  orig;         // original bytes, as linked at the preferred base
  const uint32_t* relocs;       // ascending offsets of relocated dwords, ends with 0xffffffff
  uint32_t        flags;        // MxoXNeedsDeps or 0
};

// MxoXFunc::flags: the routine relies on every entry of the dependency table being intact
const uint32_t MxoXNeedsDeps = 1;

// msvcr71.dll functions, by their number in the two import tables below
enum MxoXCrtFunction : uint32_t {
  MxoXCrtFloor = 0,
  MxoXCrtCeil  = 1,
  MxoXCrtSqrt  = 2,
};

// Entry of the crtslots table, which ends with slot 0: where the image imports a function of msvcr71.dll
struct MxoXCrtSlot {
  uint32_t slot;      // rva of the import slot
  uint32_t function;  // MxoXCrtFunction
};

// Entry of the inlined table, which ends with slot 0: a routine whose translation computes floor or ceil itself
struct MxoXInlinedImport {
  uint32_t slot;      // rva of the import slot the original calls through
  uint32_t rva;       // the routine
  uint32_t function;  // MxoXCrtFunction
};

// Entry of the xrdeps table, which ends with caller 0: a translated routine that calls another one directly
struct MxoXDirectCall {
  uint32_t caller;
  uint32_t callee;
};

// FNV-1a over [code, code + size), the hash xlat.py --write-list writes for a routine. The four bytes at each
// offset in skips hold an address and are left out, so the hash stands for the routine wherever
// its image is loaded, and no copy of its code has to be carried along.
static inline uint64_t MxoXCodeHash(const uint8_t* code, uint32_t size, const uint32_t* skips, uint32_t skipCount) {
  uint64_t hash = 0xcbf29ce484222325ull;

  for (uint32_t i = 0; i < size; ) {
    bool isAddress = false;

    for (uint32_t k = 0; k < skipCount; k++)
      isAddress = isAddress || skips[k] == i;

    if (isAddress) {
      i += sizeof(uint32_t);
    } else {
      hash = (hash ^ code[i]) * 0x100000001b3ull;
      i += 1;
    }
  }

  return hash;
}

// Points the translated code at an image loaded at 'base'. Call once.
static inline bool MxoXFixups(const uint8_t* base, uint32_t prefBase, const uint32_t* absfix,
                              const uint32_t* relfix, uint8_t* codeBegin, uint8_t* codeEnd) {
  DWORD oldProtect = 0;

  if (!::VirtualProtect(codeBegin, codeEnd - codeBegin, PAGE_EXECUTE_READWRITE, &oldProtect))
    return false;

  const uint32_t imageBase = uint32_t(uintptr_t(base));
  const uint32_t delta = imageBase - prefBase;

  for (const uint32_t* p = absfix; *p; p++) {
    uint32_t value;
    std::memcpy(&value, reinterpret_cast<void*>(uintptr_t(*p)), 4);
    value += delta;
    std::memcpy(reinterpret_cast<void*>(uintptr_t(*p)), &value, 4);
  }

  for (const uint32_t* p = relfix; p[0]; p += 2) {
    const int32_t rel = int32_t(imageBase + p[1] - (p[0] + 4));
    std::memcpy(reinterpret_cast<void*>(uintptr_t(p[0])), &rel, 4);
  }

  ::VirtualProtect(codeBegin, codeEnd - codeBegin, oldProtect, &oldProtect);
  ::FlushInstructionCache(::GetCurrentProcess(), codeBegin, codeEnd - codeBegin);
  return true;
}

// True if the image loaded at 'base' holds exactly the code the translation was made from.
static inline bool MxoXMatches(const uint8_t* base, uint32_t imageSize, uint32_t prefBase, const MxoXFunc& f) {
  if (f.rva > imageSize || f.size > imageSize - f.rva)
    return false;

  const uint32_t delta = uint32_t(uintptr_t(base)) - prefBase;
  const uint8_t* code = base + f.rva;
  const uint32_t* reloc = f.relocs;

  for (uint32_t i = 0; i < f.size; ) {
    if (*reloc == i) {
      uint32_t a, b;
      std::memcpy(&a, code + i, 4);
      std::memcpy(&b, f.orig + i, 4);
      if (a != b + delta)
        return false;
      i += 4;
      reloc++;
    } else {
      if (code[i] != f.orig[i])
        return false;
      i++;
    }
  }

  return true;
}
